-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-fee-rule-create-rpc.sql
-- Source SHA256: 095D69019BB457568DC8BDB495000D8AA7DA99CA69BF011306927020F5F0DAEE
-- Local replay required before any staging promotion.
-- OTOTR CONTRACT FEE RULE CREATE RPC CANDIDATE
create or replace function finance_private.current_fee_rule_create_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_fee_rule_create_scope(p_actor_id uuid,p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_fee_rule_create(p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.fee-rules.create' then null::jsonb else finance_private.resolve_fee_rule_create_scope(auth.uid(),p_contract_version_id,p_permission) end$$;
create or replace function finance_api.commit_fee_rule_create(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_version_id uuid,p_rule jsonb,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare v_cv record;v_fd finance.fee_definitions%rowtype;v_id uuid:=gen_random_uuid();v_existing record;v_resource jsonb;v_payload jsonb;v_previous text;v_audit text;v_config text:=p_rule->>'configurationStatus';v_evidence uuid;v_branch_ids jsonb;v_min numeric(24,8);v_max numeric(24,8);
begin
 if not finance_private.current_fee_rule_create_committer_is_trusted() then raise exception using errcode='42501',message='trusted fee rule create committer required';end if;
 if pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or pg_catalog.jsonb_typeof(p_rule)<>'object' then raise exception using errcode='22023',message='invalid fee rule create command';end if;
 if (select pg_catalog.array_agg(k order by k) from pg_catalog.jsonb_object_keys(p_rule) k) is distinct from (select pg_catalog.array_agg(k order by k) from pg_catalog.unnest(array['basis','calculation','cancellationPolicy','code','configurationStatus','evidenceDocumentId','exceptions','feeDefinitionId','tax','trigger','due']) k) then raise exception using errcode='22023',message='fee rule create fields invalid';end if;
 if coalesce(p_rule->>'code','')!~'^[A-Z][A-Z0-9_]{2,79}$' or coalesce(p_rule->>'feeDefinitionId','')!~'^[0-9a-fA-F-]{36}$' or v_config not in ('UNCONFIGURED','CONFIGURED') or pg_catalog.jsonb_typeof(coalesce(p_rule->'exceptions','[]'::jsonb))<>'array' or pg_catalog.jsonb_array_length(coalesce(p_rule->'exceptions','[]'::jsonb))<>0 then raise exception using errcode='22023',message='fee rule create values invalid';end if;
 if v_config='UNCONFIGURED' and (p_rule->'trigger' is not null or p_rule->'basis' is not null or p_rule->'calculation' is not null or p_rule->'tax' is not null or p_rule->'due' is not null or p_rule->'cancellationPolicy' is not null) then raise exception using errcode='23514',message='unconfigured fee rule cannot contain calculation payload';end if;
 if v_config='CONFIGURED' and (pg_catalog.jsonb_typeof(p_rule->'trigger')<>'object' or coalesce(p_rule#>>'{trigger,eventType}','')='' or pg_catalog.jsonb_typeof(coalesce(p_rule#>'{trigger,conditions}','[]'::jsonb))<>'array' or pg_catalog.jsonb_typeof(p_rule->'basis')<>'object' or pg_catalog.jsonb_typeof(p_rule->'calculation')<>'object' or pg_catalog.jsonb_typeof(p_rule#>'{calculation,parameters}')<>'object' or coalesce(p_rule#>>'{calculation,method}','') not in ('FIXED','PERCENTAGE','PER_UNIT','TIERED','COST_PLUS','FIXED_PLUS_VARIABLE','CONDITIONAL') or coalesce(p_rule#>>'{calculation,currency}','')!~'^[A-Z]{3}$' or coalesce(p_rule#>>'{calculation,decimalScale}','')!~'^[0-8]$' or coalesce(p_rule#>>'{calculation,roundingMode}','') not in ('HALF_UP','HALF_EVEN','DOWN','UP') or pg_catalog.jsonb_typeof(p_rule->'tax')<>'object' or coalesce(p_rule#>>'{tax,taxCodeVersionId}','')!~'^[0-9a-fA-F-]{36}$' or pg_catalog.jsonb_typeof(p_rule#>'{tax,priceIncludesTax}')<>'boolean' or pg_catalog.jsonb_typeof(p_rule->'due')<>'object' or pg_catalog.jsonb_typeof(p_rule->'cancellationPolicy')<>'object') then raise exception using errcode='23514',message='configured fee rule payload incomplete';end if;
 if p_rule#>>'{calculation,minimumAmount}' is not null then if p_rule#>>'{calculation,minimumAmount}'!~'^(0|[1-9][0-9]*)(\.[0-9]{1,8})?$' then raise exception using errcode='22023',message='minimum amount invalid';end if;v_min:=(p_rule#>>'{calculation,minimumAmount}')::numeric;end if;
 if p_rule#>>'{calculation,maximumAmount}' is not null then if p_rule#>>'{calculation,maximumAmount}'!~'^(0|[1-9][0-9]*)(\.[0-9]{1,8})?$' then raise exception using errcode='22023',message='maximum amount invalid';end if;v_max:=(p_rule#>>'{calculation,maximumAmount}')::numeric;end if;if v_min is not null and v_max is not null and v_min>v_max then raise exception using errcode='23514',message='minimum exceeds maximum';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fee-rule-create:'||p_contract_version_id::text||':'||p_idempotency_key,0));
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=p_legal_entity_id and om.event_type='CONTRACT_FEE_RULE_DRAFT_CREATED' and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','resource',v_existing.payload->'resource');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select cv.*,fc.legal_entity_id,fc.dealer_legal_entity_id,fc.status contract_status into v_cv from finance.contract_versions cv join finance.franchise_contracts fc on fc.id=cv.contract_id where cv.id=p_contract_version_id for update of cv,fc;if not found then raise exception using errcode='P0002',message='contract version not found';end if;
 if v_cv.status<>'DRAFT' or v_cv.contract_status in ('TERMINATED','DISCARDED') or v_cv.legal_entity_id<>p_legal_entity_id or v_cv.dealer_legal_entity_id<>p_dealer_legal_entity_id then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='fee rule create three dimensional scope denied';end if;
 select * into v_fd from finance.fee_definitions fd where fd.id=(p_rule->>'feeDefinitionId')::uuid and fd.status='PUBLISHED' and (fd.legal_entity_id is null or fd.legal_entity_id=p_legal_entity_id);if not found then raise exception using errcode='23514',message='published fee definition required';end if;
 if v_config='CONFIGURED' and not exists(select 1 from finance.tax_code_versions tv join finance.tax_codes tc on tc.id=tv.tax_code_id where tv.id=(p_rule#>>'{tax,taxCodeVersionId}')::uuid and tc.legal_entity_id=p_legal_entity_id and tv.status in ('APPROVED','ACTIVE')) then raise exception using errcode='23514',message='approved tax code version required';end if;
 if nullif(p_rule->>'evidenceDocumentId','') is not null then v_evidence:=(p_rule->>'evidenceDocumentId')::uuid;if not exists(select 1 from finance.document_references dr where dr.id=v_evidence and dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE') then raise exception using errcode='23514',message='active fee rule evidence required';end if;end if;
 if exists(select 1 from finance.contract_fee_rules r where r.contract_version_id=p_contract_version_id and r.rule_code=p_rule->>'code') then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 insert into finance.contract_fee_rules(id,contract_version_id,fee_definition_id,rule_code,trigger_event_type,trigger_conditions,priority,status,configuration_status,basis_definition,calculation_method,calculation_parameters,tax_code_version_id,due_rule,cancellation_policy,price_includes_tax,minimum_amount,maximum_amount,currency_code,decimal_scale,rounding_mode,prepared_by,version,created_by,correlation_id) values(v_id,p_contract_version_id,v_fd.id,p_rule->>'code',case when v_config='CONFIGURED' then p_rule#>>'{trigger,eventType}' end,case when v_config='CONFIGURED' then coalesce(p_rule#>'{trigger,conditions}','[]'::jsonb) end,0,'DRAFT',v_config,case when v_config='CONFIGURED' then p_rule->'basis' end,case when v_config='CONFIGURED' then p_rule#>>'{calculation,method}' end,case when v_config='CONFIGURED' then p_rule#>'{calculation,parameters}' end,case when v_config='CONFIGURED' then (p_rule#>>'{tax,taxCodeVersionId}')::uuid end,case when v_config='CONFIGURED' then p_rule->'due' end,case when v_config='CONFIGURED' then p_rule->'cancellationPolicy' end,case when v_config='CONFIGURED' then (p_rule#>>'{tax,priceIncludesTax}')::boolean end,v_min,v_max,case when v_config='CONFIGURED' then p_rule#>>'{calculation,currency}' end,case when v_config='CONFIGURED' then (p_rule#>>'{calculation,decimalScale}')::smallint end,case when v_config='CONFIGURED' then p_rule#>>'{calculation,roundingMode}' end,p_actor_id,1,p_actor_id,p_correlation_id);
 if v_evidence is not null then insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) values(p_legal_entity_id,v_evidence,'CONTRACT_FEE_RULE',v_id,'EVIDENCE_V1',p_actor_id,p_correlation_id);end if;
 select coalesce(pg_catalog.jsonb_agg(b.id order by b.branch_code,b.id),'[]'::jsonb) into v_branch_ids from finance.branches b where b.legal_entity_id=p_legal_entity_id and b.dealer_legal_entity_id=p_dealer_legal_entity_id and b.status='ACTIVE';
 v_resource:=pg_catalog.jsonb_build_object('feeRuleId',v_id,'feeDefinitionId',v_fd.id,'feeDefinitionVersion',v_fd.version_no,'version',1,'code',p_rule->>'code','name',v_fd.name,'category',v_fd.fee_family,'status','DRAFT','configurationStatus',v_config,'scope',pg_catalog.jsonb_build_object('headquartersLegalEntityId',p_legal_entity_id,'dealerLegalEntityId',p_dealer_legal_entity_id,'branchIds',v_branch_ids,'packageIds','[]'::jsonb,'serviceIds','[]'::jsonb),'validity',pg_catalog.jsonb_build_object('validFrom',v_cv.effective_from,'validTo',v_cv.effective_to,'contractVersionId',v_cv.id),'trigger',p_rule->'trigger','basis',p_rule->'basis','calculation',p_rule->'calculation','tax',p_rule->'tax','due',p_rule->'due','cancellationPolicy',p_rule->'cancellationPolicy','exceptions','[]'::jsonb,'createdBy',pg_catalog.jsonb_build_object('actorType','USER','actorId',p_actor_id),'createdAtUtc',pg_catalog.statement_timestamp(),'approvedBy',null,'approvedAtUtc',null,'evidenceDocumentId',v_evidence);
 v_payload:=pg_catalog.jsonb_build_object('resource',v_resource,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','CONTRACT_FEE_RULE_DRAFT_CREATED','CONTRACT_FEE_RULE',v_id,1,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v_id::text||':CONTRACT_FEE_RULE_DRAFT_CREATED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','CONTRACT_FEE_RULE_DRAFT_CREATED','CONTRACT_FEE_RULE',v_id,'ALLOW',p_intent_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('contractVersionId',p_contract_version_id,'feeDefinitionId',v_fd.id,'ruleCode',p_rule->>'code','configurationStatus',v_config,'branchId',p_branch_id),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','CREATED','resource',v_resource);
end$$;
revoke all on function finance_private.current_fee_rule_create_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_fee_rule_create_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_fee_rule_create(uuid,text) from public,anon;grant execute on function finance_api.authorize_fee_rule_create(uuid,text) to authenticated;revoke all on function finance_api.commit_fee_rule_create(uuid,uuid,uuid,uuid,uuid,uuid,jsonb,text,text,uuid) from public,anon,authenticated;
